import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry – maintain source aspect ratio (512 × 320 → 1.6 : 1)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Basic material (no lighting)
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    map: null,
    transparent: true,
    depthWrite: true,
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Async texture load
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Interaction handling
  let hoverTween = null;
  const handlers = {
    hoverEnter: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, {
        y: 0.15,
        duration: 0.2,
        ease: 'power3.out',
      });
    },
    hoverLeave: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, {
        y: 0,
        duration: 0.2,
        ease: 'power3.out',
      });
    },
    click: () => {
      ctx.emit('hub-journal.select', {});
    },
  };
  root.userData.handlers = handlers;

  // Cleanup routine
  root.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    material.dispose();
    geometry.dispose();
    // Remove references
    root.remove(mesh);
    mesh.geometry = null;
    mesh.material = null;
  };

  // No cinematic primitives to apply (config.cinematicPrimitives may be empty)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const primitive = ctx.primitives[prim.name];
      if (primitive) {
        const result = primitive(root, prim.params);
        // store for cleanup
        root.userData.cleanup = ((prev) => () => {
          if (prev) prev();
          result.cleanup?.();
        })(root.userData.cleanup);
      }
    }
  }

  return root;
}
